+	if err != nil {
+		errs = append(errs, err)
+	}
+
+	for _, node := range nodes {
+		if node.IsTagged() {
+			continue
+		}
+
+		if node.User.ID == user.ID {
+			node.AppendToIPSet(&ips)
+		}
+	}
+
+	return buildIPSetMultiErr(&ips, errs)
