+
+	switch {
+	case isWildcard(vs):
+		return Wildcard, nil
+	case isUser(vs):
+		return ptr.To(Username(vs)), nil
+	case isGroup(vs):
+		return ptr.To(Group(vs)), nil
+	case isTag(vs):
+		return ptr.To(Tag(vs)), nil
+	case isAutoGroup(vs):
+		return ptr.To(AutoGroup(vs)), nil
+	}
+
+	if isHost(vs) {
+		return ptr.To(Host(vs)), nil
+	}
